+<script lang="ts">
+  interface Props {
+    value: string | number
+    min?: number
+    max?: number
+    step?: number
+    onchange?: (value: string) => void
+    id?: string
+  }
+
+  let { value, min = 0, max = 100, step = 1, onchange, id }: Props = $props()
+
+  let editing = $state(false)
+  let editValue = $state('')
+  let displayValue = $derived(String(value))
