+      cleanup()
+    })
+    const offError = window.api.onUpdateError(() => {
+      dismiss('error')
+      cleanup()
+    })
+
+    const cleanup = (): void => {
+      offAvailable()
+      offNotAvailable()
+      offError()
+    }
